/* Stone Lock V3 | standalone browser component */
(() => {
 const player="<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Stone Lock V4</title>\n<style>\n*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;align-content:center;background:#171614;color:#eee5d8;text-align:center;font:16px system-ui}h1{font:normal 34px Georgia;margin:18px}small{font:12px system-ui;color:#beb09d}.scroll{overflow-x:auto;padding:12px 0}#stage{position:relative;margin:auto;width:max-content}canvas{display:block}#controls{display:flex;position:absolute;justify-content:center;align-items:stretch} .column{display:grid;grid-template-rows:1fr 1fr;position:relative}.column button{border:0;background:transparent;color:transparent;cursor:pointer;touch-action:manipulation}.column button:focus-visible{outline:2px solid wheat;outline-offset:-3px}details{margin:8px auto 22px;max-width:540px;padding:0 12px}summary,button{cursor:pointer}label{display:flex;align-items:center;justify-content:center;gap:8px;margin:12px 0;flex-wrap:wrap}input,select,details button{background:#292622;color:inherit;border:1px solid #756b5b;border-radius:5px;padding:8px;font:inherit}p{margin:10px;font-size:14px;color:#c5bcaf}.actions{display:flex;flex-wrap:wrap;gap:7px;justify-content:center}#msg{min-height:1em}\nbody{background:transparent;padding:0;min-height:100vh}h1,body>p,details{display:none}.scroll{padding:0;overflow:hidden}</style><h1>Stone Lock <small>V4</small></h1><div class=\"scroll\"><div id=\"stage\"><canvas id=\"view\"></canvas><div id=\"controls\"></div></div></div><p>Tap the upper or lower half of a wheel to turn it. Swipe vertically to roll.</p><details><summary>Configure lock</summary><label>Wheel <select id=\"which\"></select></label><div class=\"actions\"><button id=\"add\">Add wheel</button><button id=\"del\">Remove wheel</button><button id=\"blank\">Blank wheel</button><button id=\"numbers\">Numbers 1\u201310</button></div><label>Faces <input id=\"labels\" aria-label=\"Comma-separated face labels\"><button id=\"apply\">Apply</button></label><label>Replace face <select id=\"slot\"></select></label><label>Symbol artwork <input type=\"file\" id=\"art\" accept=\"image/png\"></label><p>Use a tightly cropped PNG silhouette with a clear background, or a black shape on white. The silhouette sets the depth of the engraving.</p><div class=\"actions\"><button id=\"save\">Save lock design</button><label style=\"margin:0\"><input id=\"load\" type=\"file\" accept=\".json\" hidden><button id=\"restore\" type=\"button\">Load design</button></label></div><p id=\"msg\" role=\"status\"></p></details>\n<script>\nconst $=id=>document.getElementById(id), W=288,H=1920,F=192,PITCH=212,SCALE=.54,HEIGHT=800,EDGE=167;\nconst img=src=>new Promise((ok,fail)=>{const i=new Image;i.onload=()=>ok(i);i.onerror=fail;i.src=src});\nconst make=(w,h)=>Object.assign(document.createElement('canvas'),{width:w,height:h});\nconst plain=()=>Array.from({length:10},(_,i)=>({text:String(i+1)}));\nlet stone,frame,wheels=[],selected=0,anim=0,scale,drag;\nconst cv=$('view'),ctx=cv.getContext('2d');\nfunction wheel(faces,pos=0){return {faces,pos,target:pos,start:pos,time:0,map:null}}\nconst mod=(a,n)=>(a%n+n)%n;\nasync function bake(w){\n const stamp=Symbol();w.stamp=stamp;\n const atlas=make(W,H),g=atlas.getContext('2d');g.drawImage(stone,0,0,W,H);\n const surface=g.getImageData(0,0,W,H), N=w.faces.length, band=H/N;\n for(const [i,face] of w.faces.entries()){\n if(!face.text&&!face.mask)continue;\n const mask=make(W,F),m=mask.getContext('2d');\n if(face.mask){const pic=await img(face.mask);const z=Math.min(188/pic.width,142/pic.height);m.drawImage(pic,(W-pic.width*z)/2,(F-pic.height*z)/2,pic.width*z,pic.height*z)}\n else{m.fillStyle='white';m.textAlign='center';m.textBaseline='alphabetic';m.font='bold 145px Georgia,serif';const metrics=m.measureText(face.text);m.fillText(face.text,W/2,(F+metrics.actualBoundingBoxAscent-metrics.actualBoundingBoxDescent)/2,W-54)}\n const soft=make(W,F),s=soft.getContext('2d');s.filter='blur(2.6px)';s.drawImage(mask,0,0);const d=s.getImageData(0,0,W,F).data;\n const dep=(x,y)=>d[(y*W+x)*4+3]/255;\n for(let y=2;y<F-2;y++)for(let x=2;x<W-2;x++){\n const depth=dep(x,y);if(!depth)continue;const nx=dep(x+2,y)-dep(x-2,y),ny=dep(x,y+2)-dep(x,y-2);\n const strength=1-.36*depth-1.08*nx-1.35*ny;\n const index=(Math.floor(i*band+(band-F)/2+y)*W+x)*4;\n for(let c=0;c<3;c++)surface.data[index+c]*=Math.max(.16,strength);\n }}\n g.putImageData(surface,0,0);if(w.stamp===stamp){w.map=atlas;paint()}\n}\nlet cachedFrame, cachedWidth;\nfunction renderFrame(width){\n if(cachedWidth!==width){\n  cachedFrame=make(width,HEIGHT);const g=cachedFrame.getContext('2d'),edge=EDGE,span=width-edge*2;\n  const cut=256,right=1275,top=29,height=960;\n  g.drawImage(frame,24,top,cut-24,height,0,0,edge,HEIGHT);\n  for(let p=0;p<span;p+=320){\n   const len=Math.min(320,span-p),flip=Math.floor(p/320)%2;g.save();\n   g.translate(edge+p+(flip?len:0),0);g.scale(flip?-1:1,1);\n   g.drawImage(frame,flip?cut+400-len*1.25:cut,top,len*1.25,height,0,0,len,HEIGHT);g.restore()\n  }\n  for(let k=0;k<45;k++){g.globalAlpha=(k+1)/45;g.drawImage(frame,right-45+k,top,1,height,width-edge-45+k,0,1.2,HEIGHT)}\n  g.globalAlpha=1;g.drawImage(frame,right,top,1534-right,height,width-edge,0,edge,HEIGHT);\n  cachedWidth=width;\n }\n ctx.clearRect(0,0,width,HEIGHT);ctx.drawImage(cachedFrame,0,0)\n}\n// Each drum has a cylindrical face and a quarter-round shoulder on either side.\n// Cache the projected geometry; only the stone texture moves as the wheel turns.\nconst profiles=new Map();\nfunction drumProfile(leftEnd,rightEnd){\n const key=Number(leftEnd)*2+Number(rightEnd);\n if(profiles.has(key))return profiles.get(key);\n const left=leftEnd?15:0,right=rightEnd?15:0,width=PITCH+left+right,height=535,count=width*height;\n const profile={left,width,height,u:new Uint16Array(count),v:new Float32Array(count),light:new Uint16Array(count),coverage:new Uint8Array(count)};\n for(let x=0;x<width;x++){\n  const edge=Math.min(x+.5,width-x-.5),bevel=20;\n  const outward=Math.max(0,1-edge/bevel),radial=Math.sqrt(1-outward*outward);\n  const axial=(x<width/2?-1:1)*outward,radius=272-bevel*(1-radial);\n  for(let y=0;y<height;y++){\n   const i=y*width+x,dy=y+.5-height/2;\n   const cover=Math.min(1,edge/.85,radius-Math.abs(dy)+.5);\n   if(cover<=0)continue;\n   const ny=Math.max(-1,Math.min(1,dy/radius)),nz=Math.sqrt(1-ny*ny);\n   const light=Math.max(0,-.56*axial+radial*(-.53*ny+.64*nz));\n   const diffuse=.36+.91*light,contact=.79+.21*Math.min(1,edge/4);\n   profile.light[i]=Math.round(256*diffuse*contact);\n   profile.u[i]=Math.min(W-1,Math.floor((x+.5)/width*W));\n   profile.v[i]=Math.asin(ny)*H/(2*Math.PI);\n   profile.coverage[i]=Math.round(255*cover)\n  }\n }\n profiles.set(key,profile);return profile\n}\nfunction drawDrum(w,index){\n const p=drumProfile(index===0,index===wheels.length-1);\n if(!w.surface||w.surface.map!==w.map||w.surface.profile!==p){\n  const canvas=make(p.width,p.height),g=canvas.getContext('2d');\n  w.surface={canvas,g,profile:p,map:w.map,source:w.map.getContext('2d').getImageData(0,0,W,H).data,pixels:g.createImageData(p.width,p.height),pos:NaN}\n }\n const s=w.surface;\n if(s.pos!==w.pos){\n  const offset=mod((w.pos+.5)/w.faces.length,1)*H+H,src=s.source,dst=s.pixels.data;\n  for(let i=0;i<p.u.length;i++){\n   if(!p.coverage[i])continue;\n   const row=p.v[i]+offset,whole=Math.floor(row),t=row-whole,y=whole%H;\n   const a=(y*W+p.u[i])*4,b=(((y+1)%H)*W+p.u[i])*4,d=i*4,k=p.light[i]/256;\n   for(let c=0;c<3;c++)dst[d+c]=(src[a+c]+t*(src[b+c]-src[a+c]))*k;\n   dst[d+3]=p.coverage[i]\n  }\n  s.g.putImageData(s.pixels,0,0);s.pos=w.pos\n }\n ctx.drawImage(s.canvas,EDGE+7+PITCH*index-p.left,139)\n}\nfunction paint(){\n if(!frame||!wheels.length)return;\n const width=EDGE*2+wheels.length*PITCH+14;\n ctx.setTransform(cv.width/width,0,0,cv.height/HEIGHT,0,0);\n renderFrame(width);\n ctx.save();ctx.beginPath();ctx.rect(EDGE-9,139,width-EDGE*2+18,535);ctx.clip();\n // Warm recessed stone remains visible where a rounded shoulder clears the opening.\n ctx.fillStyle='#44392f';ctx.fillRect(EDGE,139,width-2*EDGE,535);\n wheels.forEach((w,i)=>{if(w.map)drawDrum(w,i)});ctx.restore()\n}\nfunction size(){const width=EDGE*2+wheels.length*PITCH+14;scale=initial?Math.min(1,(innerWidth-8)/width,(innerHeight-8)/HEIGHT):Math.min(SCALE,(innerWidth-10)/(EDGE*2+PITCH+14));const dpi=Math.min(2,devicePixelRatio||1);\n cv.width=Math.round(width*scale*dpi);cv.height=Math.round(HEIGHT*scale*dpi);cv.style.width=width*scale+'px';cv.style.height=HEIGHT*scale+'px';Object.assign($('controls').style,{left:(EDGE+7)*scale+'px',top:139*scale+'px',height:535*scale+'px',width:wheels.length*PITCH*scale+'px'});paint()}\nfunction move(w,d){w.start=w.pos;w.target+=d;w.time=performance.now();if(!anim)anim=requestAnimationFrame(tick)}\nfunction tick(now){let active=false;for(const w of wheels){if(!w.time)continue;const f=Math.min(1,(now-w.time)/340);w.pos=w.start+(w.target-w.start)*(1-(1-f)**3);if(f===1)w.time=0;else active=true}paint();anim=active?requestAnimationFrame(tick):0;if(!active)window.dispatchEvent(new Event(\"lockturn\"))}\nfunction options(el,values){el.replaceChildren(...values.map((v,i)=>new Option(v,i)))}\nfunction editor(){const w=wheels[selected];$('which').value=selected;$('labels').value=w.faces.map(f=>f.text||'').join(', ');options($('slot'),w.faces.map((f,i)=>(i+1)+' \u00b7 '+(f.mask?'Artwork':f.text||'Blank')));$('add').disabled=wheels.length===10;$('del').disabled=wheels.length===1}\nfunction sync(){options($('which'),wheels.map((_,i)=>String(i+1)));$('controls').replaceChildren();\n wheels.forEach((w,i)=>{const col=document.createElement('div');col.className='column';col.style.flex='1';for(const [name,d] of [['Previous',-1],['Next',1]]){const b=document.createElement('button');b.setAttribute('aria-label',name+' face on wheel '+(i+1));b.onclick=e=>{if(e.detail&&col.suppress){col.suppress=false;return}selected=i;editor();move(w,d)};col.append(b)}\n col.style.touchAction='pan-x';col.onpointerdown=e=>{drag=e.clientY;col.suppress=false};col.onpointerup=e=>{if(drag!=null&&Math.abs(e.clientY-drag)>14){col.suppress=true;selected=i;editor();move(w,e.clientY<drag?1:-1)}drag=null};col.onpointercancel=()=>drag=null;\n col.onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();move(w,e.key==='ArrowUp'?1:-1)}};$('controls').append(col)});editor();size()}\nfunction replace(f){const w=wheels[selected];w.faces=f;w.pos=w.target=0;w.time=0;bake(w);editor()}\n$('which').onchange=e=>{selected=+e.target.value;editor()};$('apply').onclick=()=>{const f=$('labels').value.split(',').map(s=>({text:s.trim()}));if(f.length>10){$('msg').textContent='Choose up to ten faces.';return}replace(f)};\n$('add').onclick=()=>{if(wheels.length>=10)return;const w=wheel(structuredClone(wheels[selected].faces));wheels.push(w);selected=wheels.length-1;sync();bake(w);$('controls').lastChild.scrollIntoView({block:'nearest',inline:'nearest'})};\n$('del').onclick=()=>{if(wheels.length<2)return;wheels.splice(selected,1);selected=Math.min(selected,wheels.length-1);sync()};\n$('blank').onclick=()=>replace(wheels[selected].faces.map(()=>({text:''})));$('numbers').onclick=()=>replace(plain());\n$('art').onchange=async e=>{const file=e.target.files[0];if(!file)return;const w=wheels[selected],slot=+$('slot').value,url=URL.createObjectURL(file);try{const pic=await img(url),k=Math.min(1,512/Math.max(pic.width,pic.height)),tmp=make(Math.max(1,Math.round(pic.width*k)),Math.max(1,Math.round(pic.height*k))),g=tmp.getContext('2d');g.drawImage(pic,0,0,tmp.width,tmp.height);const pix=g.getImageData(0,0,tmp.width,tmp.height),a=pix.data;let alpha=false;for(let i=3;i<a.length;i+=4)if(a[i]<32){alpha=true;break}let xmin=tmp.width,ymin=tmp.height,xmax=-1,ymax=-1;for(let i=0;i<a.length;i+=4){a[i+3]=alpha?a[i+3]:255-(.2126*a[i]+.7152*a[i+1]+.0722*a[i+2]);a[i]=a[i+1]=a[i+2]=255;if(a[i+3]>16){let p=i/4,x=p%tmp.width,y=Math.floor(p/tmp.width);xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y)}}if(xmax<0)throw Error();g.putImageData(pix,0,0);const trimmed=make(xmax-xmin+1,ymax-ymin+1);trimmed.getContext('2d').drawImage(tmp,-xmin,-ymin);w.faces[slot]={text:'',mask:trimmed.toDataURL()};w.time=0;w.pos=w.target=slot;await bake(w);editor();$('slot').value=slot;$('msg').textContent='Symbol engraved.'}catch{$('msg').textContent='Could not read a silhouette from that image.'}finally{URL.revokeObjectURL(url);e.target.value=''}};\n$('save').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({version:2,wheels:wheels.map(w=>({faces:w.faces,pos:mod(w.target,w.faces.length)}))})],{type:'application/json'}));a.href=url;a.download='Stone_Lock_Design.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};\n$('restore').onclick=e=>{e.preventDefault();$('load').click()};$('load').onchange=async e=>{try{const v=JSON.parse(await e.target.files[0].text());if(v.version!==2||!Array.isArray(v.wheels)||!v.wheels.length||v.wheels.length>10)throw Error();const list=v.wheels.map(w=>{if(!Array.isArray(w.faces)||!w.faces.length||w.faces.length>10||!Number.isInteger(w.pos)||!w.faces.every(f=>typeof f.text==='string'&&(!f.mask||/^data:image\\/png;base64,/.test(f.mask))))throw Error();return wheel(w.faces,mod(w.pos,w.faces.length))});await Promise.all(list.map(bake));wheels=list;selected=0;sync();$('msg').textContent='Design loaded.'}catch{$('msg').textContent='Choose a saved V3 lock design.'}e.target.value=''};\nconst initial=window.frameElement.stoneConfig;\nwindow.lockValues=()=>wheels.map(w=>mod(w.target,w.faces.length));\nwindow.lockSettled=()=>wheels.every(w=>!w.time);\nwindow.lockSnapshot=()=>cv.toDataURL('image/png');\nPromise.all([img('data:image/jpeg;base64,'),img('data:image/webp;base64,')]).then(([a,b])=>{stone=a;frame=b;wheels=initial?initial.wheels.map(w=>wheel(w.faces,w.pos||0)):[wheel(plain(),4)];sync();Promise.all(wheels.map(bake)).then(()=>{window.stoneReady=true;window.dispatchEvent(new Event('lockready'))})});addEventListener('resize',()=>{if(wheels.length)size()});\n</script></html>\n";
 function mount(target, options={}){
  if(typeof target==='string')target=document.querySelector(target);
  if(!target)throw Error('Stone Lock needs a mount element.');
  const design=options.design||{wheels:[{faces:Array.from({length:10},(_,i)=>({text:String(i+1)})),pos:0}]};
  if(!Array.isArray(design.wheels)||design.wheels.length<1||design.wheels.length>10)throw Error('Choose one to ten wheels.');
  const config={wheels:design.wheels.map(w=>{
   if(!Array.isArray(w.faces)||w.faces.length<1||w.faces.length>10)throw Error('Choose one to ten faces per wheel.');
   const faces=w.faces.map(f=>{if(!f||typeof f.text!=='string'||(f.mask&&!/^data:image\/png;base64,[A-Za-z0-9+/=\s]+$/.test(f.mask)))throw Error('Invalid wheel face.');return {text:f.text,mask:f.mask||''}});
   return {faces,pos:Number.isInteger(w.pos)?((w.pos%faces.length)+faces.length)%faces.length:0};
  })};
  const solution=options.solution?.slice();
  if(solution&&(!Array.isArray(solution)||solution.length!==config.wheels.length||solution.some((n,i)=>!Number.isInteger(n)||n<0||n>=config.wheels[i].faces.length)))throw Error('Solution must contain one valid zero-based face index per wheel.');
  const host=document.createElement('div');target.append(host);const root=host.attachShadow({mode:'open'});
  root.innerHTML='<style>:host{display:block;width:100%}button{cursor:pointer;font:inherit}.hot{width:100%;display:block;border:0;background:transparent;padding:0}.hot img{display:block;width:100%;filter:drop-shadow(2px 3px 2px #0006)}dialog{box-sizing:border-box;padding:12px;border:0;background:transparent;color:#fff;width:min(96vw,1250px);max-width:96vw;max-height:96vh;margin:auto;text-align:center}dialog:not([open]){display:block;visibility:hidden;pointer-events:none;position:fixed;left:-200vw;right:auto}dialog::backdrop{background:#161310d9}iframe{display:block;border:0;width:100%;height:min(74vh,650px);background:transparent}.bar{display:flex;align-items:center;justify-content:center;gap:20px;font:16px system-ui}.close{padding:9px 16px;border:1px solid #958575;border-radius:6px;background:#28241f;color:white}</style><button class="hot" disabled aria-label="Open stone lock"><img alt="Stone combination lock"></button><dialog aria-label="Stone lock close-up"><iframe title="Turn the stone wheels"></iframe><div class="bar"><span role="status">Tap above or below a carving to turn the wheel.</span><button class="close">Back to game</button></div></dialog>';
  const dlg=root.querySelector('dialog'),hot=root.querySelector('.hot'),image=hot.firstChild,iframe=root.querySelector('iframe'),closeButton=root.querySelector('.close'),status=root.querySelector('[role=status]');
  let ready=false,solved=false;
  const emit=(type,detail)=>target.dispatchEvent(new CustomEvent(type,{detail,bubbles:true,composed:true}));
  const values=()=>iframe.contentWindow?.lockValues?.()||config.wheels.map(w=>w.pos);
  function snapshot(){image.src=iframe.contentWindow.lockSnapshot()}
  function opened(){if(!ready||dlg.open)return;dlg.showModal();iframe.contentWindow.dispatchEvent(new Event('resize'));closeButton.focus();emit('stone-lock-open',{values:values()})}
  function close(){if(dlg.open)dlg.close()}
  function turned(){const current=values();snapshot();emit('stone-lock-change',{values:current});if(!solved&&solution&&current.every((n,i)=>n===solution[i])){solved=true;status.textContent='Lock solved.';emit('stone-lock-solved',{values:current});options.onSolved?.(current)}}
  hot.onclick=opened;closeButton.onclick=close;
  dlg.addEventListener('close',()=>{hot.focus();emit('stone-lock-close',{values:values(),solved})});
  iframe.addEventListener('load',()=>{const win=iframe.contentWindow;
   function onReady(){ready=true;hot.disabled=false;snapshot();emit('stone-lock-ready',{values:values()})}
   if(typeof win.lockValues!=='function')return;
   win.addEventListener('lockturn',turned);win.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}});
   if(win.stoneReady)onReady();else win.addEventListener('lockready',onReady,{once:true});
  });
  iframe.stoneConfig=config;iframe.srcdoc=player;
  return {open:opened,close,getValues:values,get solved(){return solved},destroy(){host.remove()}};
 }
 window.StoneLock={mount};
})();
